 package net.sf.mpxj.reader;

+import java.io.File;
 import java.io.IOException;
+import java.nio.file.Path;
+import java.nio.file.Paths;

 /**
  * Helper methods for reader/writer implementations.
  */
 public final class ReaderWriterHelper
@@ -32,6 +35,37 @@ public final class ReaderWriterHelper
     private ReaderWriterHelper()
     {
     }
+
+    /**
+     * Validate that a child path remains within a base directory.
+     *
+     * @param baseDirectory base directory
+     * @param childPath child path
+     * @throws IOException if the resolved path escapes the base directory
+     */
+    public static void validatePathWithinBaseDirectory(File baseDirectory, String childPath) throws IOException
+    {
+        if (baseDirectory == null)
+        {
+            throw new NullPointerException("baseDirectory");
+        }
+        if (childPath == null)
+        {
+            throw new NullPointerException("childPath");
+        }
+
+        Path base = baseDirectory.getCanonicalFile().toPath();
+        Path resolved = base.resolve(Paths.get(childPath)).normalize();
+
+        if (!resolved.startsWith(base))
+        {
+            throw new IOException("Path traversal attempt detected: " + childPath);
+        }
+    }
 }
