@@ -0,0 +1,56 @@
+<?php
+
+namespace MongoDB\Driver\Monitoring\CommandSubscriber;
+
+final class SensitiveCommandRedactor
+{
+    /**
+     * Redact authentication-related fields from command monitoring events.
+     *
+     * @param array<string,mixed> $command
+     * @return array<string,mixed>
+     */
+    public static function redact(array $command): array
+    {
+        foreach (['saslStart', 'saslContinue', 'authenticate', 'getnonce', 'getNonce'] as $sensitiveCommand) {
+            if (isset($command[$sensitiveCommand])) {
+                return self::redactDocument($command, $sensitiveCommand);
+            }
+        }
+
+        return $command;
+    }
+
+    /**
+     * @param array<string,mixed> $command
+     * @return array<string,mixed>
+     */
+    private static function redactDocument(array $command, string $sensitiveCommand): array
+    {
+        if (array_key_exists($sensitiveCommand, $command)) {
+            $command[$sensitiveCommand] = true;
+        }
+
+        foreach ($command as $key => $value) {
+            if (is_array($value)) {
+                $command[$key] = self::redactNested($value);
+            }
+        }
+
+        return $command;
+    }
+
+    /**
+     * @param array<string,mixed> $value
+     * @return array<string,mixed>
+     */
+    private static function redactNested(array $value): array
+    {
+        foreach ($value as $key => $nestedValue) {
+            if (is_array($nestedValue)) {
+                $value[$key] = self::redactNested($nestedValue);
+            }
+        }
+
+        return $value;
+    }
+}

